import { type FC, useEffect, useRef, useState } from "react";

import { COLORS } from "./constants";

interface ColorPickerProps {
  label: "Text" | "Highlight";
  currentColor?: string;
  onSelect: (color: string) => void;
}

export const ColorPicker: FC<ColorPickerProps> = ({
  label,
  currentColor,
  onSelect,
}) => {
  const [open, setOpen] = useState(false);
  const [customColor, setCustomColor] = useState(currentColor ?? "#1a1915");
  const ref = useRef<HTMLDivElement>(null);
  const isText = label === "Text";

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node))
        setOpen(false);
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, []);

  return (
    <div ref={ref} className="relative">
      <button
        type="button"
        title={`${label} color`}
        onClick={() => setOpen((o) => !o)}
        className="inline-flex size-8 flex-col items-center justify-center gap-0.5 rounded-md transition-colors hover:bg-[var(--editor-surface)]"
      >
        <span className="text-[13px] leading-none font-bold text-[var(--editor-fg)]">
          {isText ? "A" : "H"}
        </span>
        <span
          className="h-[3px] w-4 rounded-full"
          style={{
            background:
              currentColor ?? (isText ? "var(--editor-fg)" : "#fef08a"),
          }}
        />
      </button>

      {open && (
        <div className="absolute top-9 left-0 z-50 w-[172px] rounded-xl border border-[var(--editor-border)] bg-[var(--editor-bg)] p-3 shadow-xl">
          <div className="mb-3 flex flex-wrap gap-1">
            {COLORS.map((c) => (
              <button
                key={c}
                type="button"
                title={c}
                onClick={() => {
                  onSelect(c);
                  setCustomColor(c);
                  setOpen(false);
                }}
                className="size-[22px] rounded-md border border-transparent transition-transform hover:scale-110"
                style={{
                  background: c,
                  borderColor:
                    c === "#ffffff" ? "var(--editor-border)" : "transparent",
                  outline:
                    currentColor === c
                      ? "2px solid var(--editor-accent)"
                      : undefined,
                  outlineOffset: "1px",
                }}
              />
            ))}
          </div>
          <div className="mb-2 h-px bg-[var(--editor-border)]" />
          <label className="group flex cursor-pointer items-center gap-2">
            <span className="text-[10px] font-semibold tracking-wider text-[var(--editor-muted-fg)] uppercase">
              Custom
            </span>
            <input
              type="color"
              value={customColor}
              onChange={(e) => {
                setCustomColor(e.target.value);
                onSelect(e.target.value);
              }}
              onBlur={() => setOpen(false)}
              className="h-7 w-full flex-1 cursor-pointer rounded-md border border-[var(--editor-border)] bg-transparent"
              style={{ padding: "1px" }}
            />
          </label>
        </div>
      )}
    </div>
  );
};

import { type Editor, useEditorState } from "@tiptap/react";
import {
  AlignCenter,
  AlignJustify,
  AlignLeft,
  AlignRight,
  Bold,
  CaseLower,
  CaseSensitive,
  CaseUpper,
  ChevronDown,
  Code,
  Code2,
  Columns2,
  Highlighter,
  ImageIcon,
  Italic,
  Link2,
  List,
  ListOrdered,
  ListTodo,
  Menu,
  Minus,
  Quote,
  Redo2,
  Rows2,
  Strikethrough,
  Subscript,
  Superscript,
  Table,
  TableCellsMerge,
  Trash2,
  Underline,
  Undo2,
  Video,
  X,
} from "lucide-react";
import { type FC, type ReactNode, useCallback, useState } from "react";
import { ColorPicker } from "./ColorPicker";
import {
  FONT_FAMILIES,
  FONT_SIZES,
  HEADING_FONT_SIZE_MAP,
  HEADING_OPTIONS,
} from "./constants";
import { LinkPopup } from "./LinkPopup";
import { cn } from "./lib/utils";
import type { EditorLocaleText } from "./locale";
import { ToolbarButton, ToolbarLabel, ToolbarSeparator } from "./ToolbarButton";
import type {
  EditorToolbarFeatures,
  HeadingLevel,
  TextAlignValue,
} from "./types";
import { DEFAULT_TOOLBAR_FEATURES } from "./types";

const Tooltip: FC<{ label: string; children: ReactNode }> = ({
  label,
  children,
}) => {
  const [show, setShow] = useState(false);
  return (
    <div
      className="relative inline-flex"
      onMouseEnter={() => setShow(true)}
      onMouseLeave={() => setShow(false)}
      onFocus={() => setShow(true)}
      onBlur={() => setShow(false)}
    >
      {children}
      {show && label && (
        <div
          role="tooltip"
          className="pointer-events-none absolute top-full left-1/2 z-[9999] mt-2 -translate-x-1/2 whitespace-nowrap rounded-md bg-[var(--editor-fg)] px-2 py-1 text-[11px] font-medium text-[var(--editor-bg)] shadow-lg"
        >
          {label}
        </div>
      )}
    </div>
  );
};

const ToolbarSelect: FC<{
  value: string;
  onChange: (v: string) => void;
  options: { value: string; label: string }[];
  widthClass?: string;
  tooltip?: string;
}> = ({ value, onChange, options, widthClass = "w-28", tooltip }) => {
  const el = (
    <div className="relative inline-flex items-center">
      <select
        value={value}
        onChange={(e) => onChange(e.target.value)}
        className={`${widthClass} h-8 cursor-pointer appearance-none rounded-md border border-[var(--editor-border)] bg-[var(--editor-surface)] pl-2 pr-6 text-xs font-medium text-[var(--editor-fg)] outline-none transition-colors hover:border-[var(--editor-muted)] focus:border-[var(--editor-accent)] focus:ring-2 focus:ring-[var(--editor-ring)]`}
      >
        {options.map((o) => (
          <option key={o.value} value={o.value}>
            {o.label}
          </option>
        ))}
      </select>
      <ChevronDown
        size={11}
        className="pointer-events-none absolute right-1.5 text-[var(--editor-muted-fg)]"
      />
    </div>
  );
  return tooltip ? <Tooltip label={tooltip}>{el}</Tooltip> : el;
};

const GL = ToolbarLabel;

interface EditorToolbarProps {
  editor: Editor;
  onOpenMedia: (type: "image" | "video") => void;
  onOpenTable: () => void;
  htmlMode: boolean;
  onToggleHtml: () => void;
  features?: Required<EditorToolbarFeatures>;
  locale: EditorLocaleText;
  className?: string;
}

export const EditorToolbar: FC<EditorToolbarProps> = ({
  editor,
  onOpenMedia,
  onOpenTable,
  htmlMode,
  onToggleHtml,
  features = DEFAULT_TOOLBAR_FEATURES,
  locale,
  className,
}) => {
  const [linkOpen, setLinkOpen] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  const f = features;

  // ── Subscribe to live editor state so dropdowns re-render on cursor move ──
  // useEditorState returns a snapshot that updates whenever the editor state changes.
  const editorState = useEditorState({
    editor,
    selector: (ctx) => {
      const e = ctx.editor;
      // Heading level
      let headingVal = "p";
      for (let l = 1; l <= 6; l++) {
        if (e.isActive("heading", { level: l })) {
          headingVal = String(l);
          break;
        }
      }
      // textStyle attributes
      const tsAttrs = e.getAttributes("textStyle");
      const explicitSize: string = tsAttrs.fontSize ?? "";
      const fontFamily: string = tsAttrs.fontFamily ?? "";
      const textTransform: string = tsAttrs.textTransform ?? "";
      const color: string = tsAttrs.color ?? "#000000";

      // Font size: explicit inline size wins; else use heading-level default
      const fontSize =
        explicitSize || HEADING_FONT_SIZE_MAP[headingVal] || "16px";

      return {
        headingVal,
        fontSize,
        fontFamily,
        textTransform,
        color,
        isBold: e.isActive("bold"),
        isItalic: e.isActive("italic"),
        isUnderline: e.isActive("underline"),
        isStrike: e.isActive("strike"),
        isHighlight: e.isActive("highlight"),
        isSubscript: e.isActive("subscript"),
        isSuperscript: e.isActive("superscript"),
        isCode: e.isActive("code"),
        isCodeBlock: e.isActive("codeBlock"),
        isLink: e.isActive("link"),
        isBlockquote: e.isActive("blockquote"),
        isBulletList: e.isActive("bulletList"),
        isOrderedList: e.isActive("orderedList"),
        isTaskList: e.isActive("taskList"),
        isTable: e.isActive("table"),
        alignLeft: e.isActive({ textAlign: "left" }),
        alignCenter: e.isActive({ textAlign: "center" }),
        alignRight: e.isActive({ textAlign: "right" }),
        alignJustify: e.isActive({ textAlign: "justify" }),
      };
    },
  });

  const s = editorState;

  // ── Heading ────────────────────────────────────────────────────────────────
  const setHeading = useCallback(
    (val: string) => {
      if (val === "p") editor.chain().focus().setParagraph().run();
      else
        editor
          .chain()
          .focus()
          .setHeading({ level: parseInt(val, 10) as HeadingLevel })
          .run();
    },
    [editor],
  );

  // ── Font size ──────────────────────────────────────────────────────────────
  const setFontSize = useCallback(
    (val: string) => {
      if (!val) editor.chain().focus().unsetFontSize().run();
      else editor.chain().focus().setFontSize(val).run();
    },
    [editor],
  );

  // ── Font family ────────────────────────────────────────────────────────────
  const setFontFamily = useCallback(
    (val: string) => {
      if (!val) editor.chain().focus().unsetFontFamily().run();
      else editor.chain().focus().setFontFamily(val).run();
    },
    [editor],
  );

  // ── Text transform ─────────────────────────────────────────────────────────
  const cycleTransform = useCallback(
    (val: string) => {
      if (s.textTransform === val)
        editor.chain().focus().unsetTextTransform().run();
      else editor.chain().focus().setTextTransform(val).run();
    },
    [editor, s.textTransform],
  );

  const setTextAlign = useCallback(
    (align: TextAlignValue) => {
      editor.chain().focus().setTextAlign(align).run();
    },
    [editor],
  );

  // ── Rows ───────────────────────────────────────────────────────────────────
  const Row1 = () => (
    <div className="flex min-h-[44px] flex-wrap items-center gap-0.5 border-b border-[var(--editor-border)] px-2 py-1.5">
      {f.history && (
        <>
          <Tooltip label={locale.undo}>
            <ToolbarButton onClick={() => editor.chain().focus().undo().run()}>
              <Undo2 size={14} />
            </ToolbarButton>
          </Tooltip>
          <Tooltip label={locale.redo}>
            <ToolbarButton onClick={() => editor.chain().focus().redo().run()}>
              <Redo2 size={14} />
            </ToolbarButton>
          </Tooltip>
          <ToolbarSeparator />
        </>
      )}

      {f.headings && (
        <>
          <ToolbarSelect
            value={s.headingVal}
            onChange={setHeading}
            options={HEADING_OPTIONS.map((o) => ({
              value: o.value,
              label: o.label,
            }))}
            widthClass="w-[112px]"
            tooltip="Text style"
          />
          <ToolbarSeparator />
        </>
      )}

      {f.fonts && (
        <>
          <ToolbarSelect
            value={s.fontFamily}
            onChange={setFontFamily}
            options={FONT_FAMILIES.map((fam) => ({
              value: fam.value,
              label: fam.label,
            }))}
            widthClass="w-[108px]"
            tooltip="Font family"
          />
          <ToolbarSelect
            value={s.fontSize}
            onChange={setFontSize}
            options={FONT_SIZES.map((sz) => ({ value: sz, label: sz }))}
            widthClass="w-[76px]"
            tooltip="Font size"
          />
          <ToolbarSeparator />
        </>
      )}

      {f.marks && (
        <>
          <Tooltip label={locale.bold}>
            <ToolbarButton
              onClick={() => editor.chain().focus().toggleBold().run()}
              active={s.isBold}
            >
              <Bold size={14} />
            </ToolbarButton>
          </Tooltip>
          <Tooltip label={locale.italic}>
            <ToolbarButton
              onClick={() => editor.chain().focus().toggleItalic().run()}
              active={s.isItalic}
            >
              <Italic size={14} />
            </ToolbarButton>
          </Tooltip>
          <Tooltip label={locale.underline}>
            <ToolbarButton
              onClick={() => editor.chain().focus().toggleUnderline().run()}
              active={s.isUnderline}
            >
              <Underline size={14} />
            </ToolbarButton>
          </Tooltip>
          <Tooltip label={locale.strike}>
            <ToolbarButton
              onClick={() => editor.chain().focus().toggleStrike().run()}
              active={s.isStrike}
            >
              <Strikethrough size={14} />
            </ToolbarButton>
          </Tooltip>
          <Tooltip label={locale.highlight}>
            <ToolbarButton
              onClick={() => editor.chain().focus().toggleHighlight().run()}
              active={s.isHighlight}
            >
              <Highlighter size={14} />
            </ToolbarButton>
          </Tooltip>
          <ToolbarSeparator />
        </>
      )}

      {f.color && (
        <>
          <ColorPicker
            label="Text"
            currentColor={s.color}
            onSelect={(c) => editor.chain().focus().setColor(c).run()}
          />
          <ToolbarSeparator />
        </>
      )}

      {f.transform && (
        <>
          <Tooltip label="UPPERCASE">
            <ToolbarButton
              onClick={() => cycleTransform("uppercase")}
              active={s.textTransform === "uppercase"}
            >
              <CaseUpper size={14} />
            </ToolbarButton>
          </Tooltip>
          <Tooltip label="lowercase">
            <ToolbarButton
              onClick={() => cycleTransform("lowercase")}
              active={s.textTransform === "lowercase"}
            >
              <CaseLower size={14} />
            </ToolbarButton>
          </Tooltip>
          <Tooltip label="Capitalize">
            <ToolbarButton
              onClick={() => cycleTransform("capitalize")}
              active={s.textTransform === "capitalize"}
            >
              <CaseSensitive size={14} />
            </ToolbarButton>
          </Tooltip>
          <ToolbarSeparator />
        </>
      )}

      {f.script && (
        <>
          <Tooltip label="Subscript">
            <ToolbarButton
              onClick={() => editor.chain().focus().toggleSubscript().run()}
              active={s.isSubscript}
            >
              <Subscript size={14} />
            </ToolbarButton>
          </Tooltip>
          <Tooltip label="Superscript">
            <ToolbarButton
              onClick={() => editor.chain().focus().toggleSuperscript().run()}
              active={s.isSuperscript}
            >
              <Superscript size={14} />
            </ToolbarButton>
          </Tooltip>
          <ToolbarSeparator />
        </>
      )}

      {f.link && (
        <div className="relative">
          <Tooltip label={locale.link}>
            <ToolbarButton
              onClick={() => setLinkOpen((o) => !o)}
              active={s.isLink}
            >
              <Link2 size={14} />
            </ToolbarButton>
          </Tooltip>
          {linkOpen && (
            <LinkPopup
              editor={editor}
              onClose={() => setLinkOpen(false)}
              locale={locale}
            />
          )}
        </div>
      )}

      {f.code && (
        <>
          <Tooltip label={locale.code}>
            <ToolbarButton
              onClick={() => editor.chain().focus().toggleCode().run()}
              active={s.isCode}
            >
              <Code size={14} />
            </ToolbarButton>
          </Tooltip>
          <Tooltip label={locale.codeBlock}>
            <ToolbarButton
              onClick={() => editor.chain().focus().toggleCodeBlock().run()}
              active={s.isCodeBlock}
            >
              <Code2 size={14} />
            </ToolbarButton>
          </Tooltip>
          <ToolbarSeparator />
        </>
      )}

      {f.html && (
        <Tooltip label={htmlMode ? locale.visualMode : locale.htmlMode}>
          <ToolbarButton onClick={onToggleHtml} active={htmlMode}>
            <span className="font-mono text-[11px] leading-none font-bold">
              &lt;/&gt;
            </span>
          </ToolbarButton>
        </Tooltip>
      )}
    </div>
  );

  const Row2 = () => (
    <div className="flex min-h-[44px] flex-wrap items-center gap-0.5 px-2 py-1.5">
      {f.align && (
        <>
          <GL>Align</GL>
          <Tooltip label={locale.alignLeft}>
            <ToolbarButton
              onClick={() => setTextAlign("left")}
              active={s.alignLeft}
            >
              <AlignLeft size={14} />
            </ToolbarButton>
          </Tooltip>
          <Tooltip label={locale.alignCenter}>
            <ToolbarButton
              onClick={() => setTextAlign("center")}
              active={s.alignCenter}
            >
              <AlignCenter size={14} />
            </ToolbarButton>
          </Tooltip>
          <Tooltip label={locale.alignRight}>
            <ToolbarButton
              onClick={() => setTextAlign("right")}
              active={s.alignRight}
            >
              <AlignRight size={14} />
            </ToolbarButton>
          </Tooltip>
          <Tooltip label={locale.alignJustify}>
            <ToolbarButton
              onClick={() => setTextAlign("justify")}
              active={s.alignJustify}
            >
              <AlignJustify size={14} />
            </ToolbarButton>
          </Tooltip>
          <ToolbarSeparator />
        </>
      )}

      {f.lists && (
        <>
          <GL>Lists</GL>
          <Tooltip label={locale.bulletList}>
            <ToolbarButton
              onClick={() => editor.chain().focus().toggleBulletList().run()}
              active={s.isBulletList}
            >
              <List size={14} />
            </ToolbarButton>
          </Tooltip>
          <Tooltip label={locale.orderedList}>
            <ToolbarButton
              onClick={() => editor.chain().focus().toggleOrderedList().run()}
              active={s.isOrderedList}
            >
              <ListOrdered size={14} />
            </ToolbarButton>
          </Tooltip>
          <Tooltip label={locale.taskList}>
            <ToolbarButton
              onClick={() => editor.chain().focus().toggleTaskList().run()}
              active={s.isTaskList}
            >
              <ListTodo size={14} />
            </ToolbarButton>
          </Tooltip>
          <ToolbarSeparator />
        </>
      )}

      <GL>Insert</GL>
      {f.quote && (
        <Tooltip label={locale.blockquote}>
          <ToolbarButton
            onClick={() => editor.chain().focus().toggleBlockquote().run()}
            active={s.isBlockquote}
          >
            <Quote size={14} />
          </ToolbarButton>
        </Tooltip>
      )}
      {f.rule && (
        <Tooltip label={locale.horizontalRule}>
          <ToolbarButton
            onClick={() => editor.chain().focus().setHorizontalRule().run()}
          >
            <Minus size={14} />
          </ToolbarButton>
        </Tooltip>
      )}
      {f.table && (
        <Tooltip label={locale.insertTable}>
          <ToolbarButton onClick={onOpenTable} active={s.isTable}>
            <Table size={14} />
          </ToolbarButton>
        </Tooltip>
      )}
      {f.image && (
        <Tooltip label={locale.insertImage}>
          <ToolbarButton onClick={() => onOpenMedia("image")}>
            <ImageIcon size={14} />
          </ToolbarButton>
        </Tooltip>
      )}
      {f.video && (
        <Tooltip label={locale.insertVideo}>
          <ToolbarButton onClick={() => onOpenMedia("video")}>
            <Video size={14} />
          </ToolbarButton>
        </Tooltip>
      )}

      {f.table && s.isTable && (
        <>
          <ToolbarSeparator />
          <GL>Table</GL>
          <Tooltip label="Add column after">
            <ToolbarButton
              onClick={() => editor.chain().focus().addColumnAfter().run()}
            >
              <Columns2 size={14} />
            </ToolbarButton>
          </Tooltip>
          <Tooltip label="Add row after">
            <ToolbarButton
              onClick={() => editor.chain().focus().addRowAfter().run()}
            >
              <Rows2 size={14} />
            </ToolbarButton>
          </Tooltip>
          <Tooltip label="Merge cells">
            <ToolbarButton
              onClick={() => editor.chain().focus().mergeCells().run()}
            >
              <TableCellsMerge size={14} />
            </ToolbarButton>
          </Tooltip>
          <Tooltip label="Delete table">
            <ToolbarButton
              onClick={() => editor.chain().focus().deleteTable().run()}
              className="text-[var(--editor-danger)] hover:bg-[var(--editor-danger-bg)]"
            >
              <Trash2 size={14} />
            </ToolbarButton>
          </Tooltip>
        </>
      )}
    </div>
  );

  return (
    <div
      className={cn(
        "itzsa-editor-toolbar sticky top-0 z-40 border-b border-[var(--editor-border)]",
        className,
      )}
      role="toolbar"
      aria-label="Formatting"
    >
      <div className="hidden sm:block">
        <Row1 />
        <Row2 />
      </div>

      <div className="sm:hidden">
        <div className="flex items-center justify-between border-b border-[var(--editor-border)] px-2 py-1.5">
          <div className="flex flex-wrap items-center gap-0.5">
            {f.history && (
              <>
                <ToolbarButton
                  onClick={() => editor.chain().focus().undo().run()}
                >
                  <Undo2 size={14} />
                </ToolbarButton>
                <ToolbarButton
                  onClick={() => editor.chain().focus().redo().run()}
                >
                  <Redo2 size={14} />
                </ToolbarButton>
                <ToolbarSeparator />
              </>
            )}
            {f.marks && (
              <>
                <ToolbarButton
                  onClick={() => editor.chain().focus().toggleBold().run()}
                  active={s.isBold}
                >
                  <Bold size={14} />
                </ToolbarButton>
                <ToolbarButton
                  onClick={() => editor.chain().focus().toggleItalic().run()}
                  active={s.isItalic}
                >
                  <Italic size={14} />
                </ToolbarButton>
                <ToolbarButton
                  onClick={() => editor.chain().focus().toggleUnderline().run()}
                  active={s.isUnderline}
                >
                  <Underline size={14} />
                </ToolbarButton>
                <ToolbarSeparator />
              </>
            )}
            {f.lists && (
              <>
                <ToolbarButton
                  onClick={() =>
                    editor.chain().focus().toggleBulletList().run()
                  }
                  active={s.isBulletList}
                >
                  <List size={14} />
                </ToolbarButton>
                <ToolbarButton
                  onClick={() =>
                    editor.chain().focus().toggleOrderedList().run()
                  }
                  active={s.isOrderedList}
                >
                  <ListOrdered size={14} />
                </ToolbarButton>
                <ToolbarSeparator />
              </>
            )}
            {f.html && (
              <ToolbarButton onClick={onToggleHtml} active={htmlMode}>
                <span className="font-mono text-[11px] leading-none font-bold">
                  &lt;/&gt;
                </span>
              </ToolbarButton>
            )}
          </div>
          <ToolbarButton
            onClick={() => setMobileOpen((o) => !o)}
            aria-expanded={mobileOpen}
            aria-label="More tools"
          >
            {mobileOpen ? <X size={14} /> : <Menu size={14} />}
          </ToolbarButton>
        </div>

        {mobileOpen && (
          <div className="overflow-x-auto border-b border-[var(--editor-border)] bg-[var(--editor-bg)]">
            <Row1 />
            <Row2 />
          </div>
        )}
      </div>
    </div>
  );
};

import { Extension } from "@tiptap/core";
import { Plugin, PluginKey } from "@tiptap/pm/state";

// ─── Unicode helpers ──────────────────────────────────────────────────────────

/**
 * Returns true if `text` contains at least one character that is *forbidden*
 * for the given language lock.
 *
 *  'en'  → forbids Devanagari (U+0900–U+097F) + Vedic/extended Devanagari
 *  'ne'  → forbids Basic Latin letters A–Z / a–z only
 *
 * Shared characters (digits, punctuation, whitespace) are never blocked.
 */
function hasForbidden(text: string, language: "en" | "ne"): boolean {
  if (language === "en") {
    return /[\u0900-\u097F\u1CD0-\u1CFF\uA8E0-\uA8FF]/.test(text);
  }
  // 'ne': block plain Latin letters; leave digits/punctuation/symbols alone
  return /[A-Za-z]/.test(text);
}

/**
 * Strips forbidden characters from pasted text so the valid portion still lands.
 */
function stripForbidden(text: string, language: "en" | "ne"): string {
  if (language === "en") {
    return text.replace(/[\u0900-\u097F\u1CD0-\u1CFF\uA8E0-\uA8FF]/g, "");
  }
  return text.replace(/[A-Za-z]/g, "");
}

// ─── Extension ────────────────────────────────────────────────────────────────

export interface LanguageGuardOptions {
  /**
   * Which script this field is locked to.
   * Derived automatically from the `nepali` prop:
   *   nepali truthy  → 'ne'
   *   nepali falsy   → 'en'
   */
  language: "en" | "ne";

  /**
   * Fired whenever input is blocked/stripped.
   * Use it to show a transient warning in the editor UI.
   */
  onBlocked?: (reason: "keystroke" | "paste") => void;
}

const pluginKey = new PluginKey("languageGuard");

export const LanguageGuard = Extension.create<LanguageGuardOptions>({
  name: "languageGuard",

  addOptions() {
    return {
      language: "en",
      onBlocked: undefined,
    };
  },

  addProseMirrorPlugins() {
    const { language, onBlocked } = this.options;

    return [
      new Plugin({
        key: pluginKey,

        props: {
          // ── Block individual keystrokes ─────────────────────────────
          handleKeyDown(_view, event) {
            // Only printable single characters
            if (event.key.length !== 1) return false;
            // Never block shortcuts (Ctrl-C, Cmd-V, etc.)
            if (event.ctrlKey || event.metaKey || event.altKey) return false;

            if (hasForbidden(event.key, language)) {
              onBlocked?.("keystroke");
              return true; // consumed — keystroke is dropped
            }
            return false;
          },

          // ── Filter paste ────────────────────────────────────────────
          handlePaste(view, event) {
            const clipboard = event.clipboardData;
            if (!clipboard) return false;

            const rawText = clipboard.getData("text/plain");
            if (!hasForbidden(rawText, language)) return false; // clean, let TipTap handle

            event.preventDefault();

            const clean = stripForbidden(rawText, language);
            if (clean.length > 0) {
              const { state, dispatch } = view;
              dispatch(state.tr.insertText(clean));
            }

            onBlocked?.("paste");
            return true;
          },
        },
      }),
    ];
  },
});

import type { Editor } from "@tiptap/react";
import { Check, Trash2 } from "lucide-react";
import { type FC, useCallback, useEffect, useRef, useState } from "react";
import type { EditorLocaleText } from "./locale";
import { validateLinkHref } from "./security";

interface LinkPopupProps {
  editor: Editor;
  onClose: () => void;
  locale: EditorLocaleText;
}

export const LinkPopup: FC<LinkPopupProps> = ({ editor, onClose, locale }) => {
  const [url, setUrl] = useState(() => editor.getAttributes("link").href ?? "");
  const [error, setError] = useState<string | null>(null);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) onClose();
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    document.addEventListener("mousedown", handler);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("mousedown", handler);
      document.removeEventListener("keydown", onKey);
    };
  }, [onClose]);

  const apply = useCallback(() => {
    if (!url.trim()) {
      editor.chain().focus().unsetLink().run();
      onClose();
      return;
    }
    const result = validateLinkHref(url);
    if (!result.ok) {
      setError(result.error);
      return;
    }
    editor
      .chain()
      .focus()
      .setLink({
        href: result.href,
        target: "_blank",
        rel: "noopener noreferrer nofollow",
      })
      .run();
    onClose();
  }, [editor, url, onClose]);

  const remove = useCallback(() => {
    editor.chain().focus().unsetLink().run();
    onClose();
  }, [editor, onClose]);

  return (
    <div
      ref={ref}
      role="dialog"
      aria-label={locale.link}
      className="absolute top-10 left-0 z-50 flex min-w-[min(100vw-2rem,320px)] flex-col gap-1.5 rounded-lg border border-[var(--editor-border)] bg-[var(--editor-bg)] p-2 shadow-xl"
    >
      <div className="flex items-center gap-2">
        <input
          type="url"
          placeholder={locale.linkPlaceholder}
          value={url}
          onChange={(e) => {
            setUrl(e.target.value);
            setError(null);
          }}
          onKeyDown={(e) => {
            if (e.key === "Enter") apply();
          }}
          className="h-8 flex-1 rounded-md border border-[var(--editor-border)] bg-[var(--editor-surface)] px-3 font-mono text-sm text-[var(--editor-fg)] outline-none focus:border-[var(--editor-accent)] focus:ring-2 focus:ring-[var(--editor-ring)]"
          aria-invalid={!!error}
        />
        <button
          type="button"
          onClick={apply}
          className="itzsa-editor-btn-primary flex size-8 items-center justify-center rounded-md transition-colors"
          aria-label={locale.link}
        >
          <Check size={13} />
        </button>
        {editor.isActive("link") && (
          <button
            type="button"
            onClick={remove}
            className="flex size-8 items-center justify-center rounded-md bg-[var(--editor-danger-bg)] text-[var(--editor-danger)] transition-colors"
            aria-label={locale.unlink}
          >
            <Trash2 size={13} />
          </button>
        )}
      </div>
      {error && (
        <p
          className="px-1 text-[11px] text-[var(--editor-danger)]"
          role="alert"
        >
          {error}
        </p>
      )}
    </div>
  );
};

import { ImageIcon, Upload, Video, X } from "lucide-react";
import {
  type FC,
  type FormEvent,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { cn } from "./lib/utils";
import type { EditorLocaleText } from "./locale";
import { sanitizeUrl } from "./security";
import {
  acceptAttr,
  type EditorMediaKind,
  formatBytes,
  type ResolvedMediaSettings,
  validateUploadFile,
} from "./upload";

interface MediaModalProps {
  type: EditorMediaKind;
  onClose: () => void;
  onInsert: (src: string, width?: string) => void;
  media: ResolvedMediaSettings;
  locale: EditorLocaleText;
  error?: string | null;
}

const SIZE_PRESETS = [
  { label: "S", value: "25%" },
  { label: "M", value: "50%" },
  { label: "L", value: "75%" },
  { label: "Full", value: "100%" },
] as const;

export const MediaModal: FC<MediaModalProps> = ({
  type,
  onClose,
  onInsert,
  media,
  locale,
  error: externalError,
}) => {
  const [url, setUrl] = useState("");
  const [preview, setPreview] = useState<string | null>(null);
  const [width, setWidth] = useState("100%");
  const [localError, setLocalError] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [dragOver, setDragOver] = useState(false);
  const fileRef = useRef<HTMLInputElement>(null);
  const dialogRef = useRef<HTMLDivElement>(null);
  const abortRef = useRef<AbortController | null>(null);
  const isImage = type === "image";
  const canUpload = typeof media.onUpload === "function";
  const maxBytes = isImage ? media.maxImageBytes : media.maxVideoBytes;
  const accept = isImage ? media.acceptImage : media.acceptVideo;

  /** Only bind sanitized URLs to <img> — never raw typed input. */
  const safePreviewSrc = useMemo(() => {
    const candidate = preview || url;
    if (!candidate.trim()) return null;
    return sanitizeUrl(candidate, {
      allowDataImage: false,
      allowRelative: true,
    });
  }, [preview, url]);

  useEffect(() => {
    const prev = document.activeElement as HTMLElement | null;
    dialogRef.current?.querySelector<HTMLElement>("input,button")?.focus();
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    document.addEventListener("keydown", onKey);
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.removeEventListener("keydown", onKey);
      document.body.style.overflow = prevOverflow;
      abortRef.current?.abort();
      prev?.focus?.();
    };
  }, [onClose]);

  const error = externalError || localError;

  const uploadFile = async (file: File) => {
    setLocalError(null);
    setProgress(0);

    if (!media.onUpload) {
      setLocalError(locale.mediaUploadMissing);
      return;
    }

    const check = validateUploadFile(file, type, media);
    if (!check.ok) {
      setLocalError(check.error);
      return;
    }

    abortRef.current?.abort();
    const ac = new AbortController();
    abortRef.current = ac;

    setUploading(true);
    try {
      const remote = await media.onUpload(file, {
        kind: type,
        signal: ac.signal,
        onProgress: (p) => setProgress(Math.max(0, Math.min(1, p.ratio))),
      });

      if (ac.signal.aborted) return;

      const safe = sanitizeUrl(remote, {
        allowDataImage: false,
        allowRelative: true,
      });
      if (!safe || safe.startsWith("data:")) {
        setLocalError(locale.mediaUploadInvalidUrl);
        return;
      }
      setPreview(safe);
      setUrl("");
      setProgress(1);
    } catch (err) {
      if (ac.signal.aborted) return;
      const message =
        err instanceof Error && err.message
          ? err.message
          : locale.mediaUploadFailed;
      setLocalError(message);
    } finally {
      if (!ac.signal.aborted) setUploading(false);
    }
  };

  const handleInsert = (e?: FormEvent) => {
    e?.preventDefault();
    const src = preview || url;
    if (!src) return;
    if (!preview && !media.allowUrlInsert) {
      setLocalError(locale.mediaUrlDisabled);
      return;
    }
    onInsert(src, isImage ? width : undefined);
  };

  const src = preview || url;
  const canInsert = Boolean(src?.trim()) && (!!preview || media.allowUrlInsert);
  const title = isImage ? locale.mediaImageTitle : locale.mediaVideoTitle;

  return (
    <div
      className="itzsa-editor-modal-backdrop fixed inset-0 z-[200] flex items-center justify-center p-4"
      onClick={(e) => e.target === e.currentTarget && onClose()}
      role="presentation"
    >
      <div
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby="itzsa-media-modal-title"
        className="itzsa-editor-modal flex max-h-[min(90vh,640px)] w-full max-w-[440px] flex-col overflow-hidden"
      >
        {/* Header */}
        <div className="flex shrink-0 items-center justify-between gap-3 border-b border-[var(--editor-border)] px-5 py-3.5">
          <div className="flex min-w-0 items-center gap-2.5">
            <div className="flex size-8 shrink-0 items-center justify-center rounded-lg bg-[var(--editor-surface)] text-[var(--editor-muted)]">
              {isImage ? (
                <ImageIcon size={15} strokeWidth={1.75} />
              ) : (
                <Video size={15} strokeWidth={1.75} />
              )}
            </div>
            <h2
              id="itzsa-media-modal-title"
              className="truncate text-[14px] font-semibold tracking-tight text-[var(--editor-fg)]"
            >
              {title}
            </h2>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="flex size-8 shrink-0 items-center justify-center rounded-lg text-[var(--editor-muted)] transition-colors hover:bg-[var(--editor-surface)] hover:text-[var(--editor-fg)]"
            aria-label="Close"
          >
            <X size={15} strokeWidth={1.75} />
          </button>
        </div>

        <form onSubmit={handleInsert} className="flex min-h-0 flex-1 flex-col">
          <div className="space-y-4 overflow-y-auto px-5 py-4">
            {media.allowUrlInsert && (
              <>
                <div>
                  <label className="mb-1.5 block text-[10px] font-semibold tracking-[0.12em] text-[var(--editor-muted)] uppercase">
                    {locale.mediaUrlLabel}
                  </label>
                  <input
                    type="url"
                    placeholder={`https://example.com/${isImage ? "image.jpg" : "video.mp4"}`}
                    value={url}
                    onChange={(e) => {
                      setUrl(e.target.value);
                      setPreview(null);
                      setLocalError(null);
                    }}
                    className="h-10 w-full rounded-lg border border-[var(--editor-border)] bg-[var(--editor-surface)] px-3 font-mono text-[13px] text-[var(--editor-fg)] outline-none transition-[border,box-shadow] placeholder:text-[var(--editor-muted-fg)] focus:border-[var(--editor-accent)] focus:ring-2 focus:ring-[var(--editor-ring)]"
                  />
                </div>

                <div className="flex items-center gap-3" aria-hidden>
                  <div className="h-px flex-1 bg-[var(--editor-border)]" />
                  <span className="text-[11px] font-medium text-[var(--editor-muted-fg)]">
                    or
                  </span>
                  <div className="h-px flex-1 bg-[var(--editor-border)]" />
                </div>
              </>
            )}

            <div>
              <label className="mb-1.5 block text-[10px] font-semibold tracking-[0.12em] text-[var(--editor-muted)] uppercase">
                {locale.mediaUploadLabel}
              </label>
              <button
                type="button"
                onClick={() => {
                  if (!canUpload) {
                    setLocalError(locale.mediaUploadMissing);
                    return;
                  }
                  fileRef.current?.click();
                }}
                onDragEnter={(e) => {
                  e.preventDefault();
                  setDragOver(true);
                }}
                onDragLeave={(e) => {
                  e.preventDefault();
                  setDragOver(false);
                }}
                onDragOver={(e) => e.preventDefault()}
                onDrop={(e) => {
                  e.preventDefault();
                  setDragOver(false);
                  if (!canUpload) {
                    setLocalError(locale.mediaUploadMissing);
                    return;
                  }
                  const file = e.dataTransfer.files?.[0];
                  if (file) void uploadFile(file);
                }}
                disabled={uploading}
                className={cn(
                  "flex w-full flex-col items-center justify-center gap-2 rounded-xl border-2 border-dashed px-4 py-7 transition-colors",
                  dragOver
                    ? "border-[var(--editor-accent)] bg-[color-mix(in_oklab,var(--editor-accent)_8%,transparent)]"
                    : "border-[var(--editor-border)] bg-[var(--editor-surface)] hover:border-[var(--editor-accent)] hover:bg-[var(--editor-surface-2)]",
                  "disabled:cursor-wait disabled:opacity-70",
                )}
              >
                <span className="flex size-10 items-center justify-center rounded-full bg-[var(--editor-bg)] text-[var(--editor-muted)] shadow-sm ring-1 ring-[var(--editor-border)]">
                  <Upload size={18} strokeWidth={1.75} />
                </span>
                <p className="text-[13px] font-medium text-[var(--editor-fg)]">
                  {uploading
                    ? locale.mediaUploading
                    : canUpload
                      ? locale.mediaUploadHint
                      : locale.mediaUploadMissingShort}
                </p>
                <p className="text-[11px] text-[var(--editor-muted-fg)]">
                  {isImage ? "PNG, JPG, GIF, WebP" : "MP4, WebM, OGG"} · max{" "}
                  {formatBytes(maxBytes)}
                </p>
                {uploading && (
                  <div
                    className="mt-1 h-1.5 w-full max-w-[220px] overflow-hidden rounded-full bg-[var(--editor-border)]"
                    role="progressbar"
                    aria-valuenow={Math.round(progress * 100)}
                    aria-valuemin={0}
                    aria-valuemax={100}
                  >
                    <div
                      className="h-full rounded-full bg-[var(--editor-accent)] transition-[width] duration-150"
                      style={{ width: `${Math.round(progress * 100)}%` }}
                    />
                  </div>
                )}
              </button>
              <input
                ref={fileRef}
                type="file"
                accept={acceptAttr(accept)}
                onChange={(e) => {
                  const file = e.target.files?.[0];
                  e.target.value = "";
                  if (file) void uploadFile(file);
                }}
                className="hidden"
              />
            </div>

            {isImage && safePreviewSrc && (
              <div className="overflow-hidden rounded-xl border border-[var(--editor-border)] bg-[var(--editor-surface)] p-2">
                <img
                  src={safePreviewSrc}
                  alt=""
                  className="mx-auto max-h-[140px] rounded-lg object-contain"
                  style={{ width }}
                />
              </div>
            )}

            {isImage && (
              <div>
                <label className="mb-1.5 block text-[10px] font-semibold tracking-[0.12em] text-[var(--editor-muted)] uppercase">
                  {locale.mediaSizeLabel}
                </label>
                <div className="flex flex-wrap gap-1.5">
                  {SIZE_PRESETS.map((p) => (
                    <button
                      key={p.value}
                      type="button"
                      onClick={() => setWidth(p.value)}
                      className={cn(
                        "h-8 min-w-[2.75rem] rounded-lg px-3 text-[12px] font-medium transition-colors",
                        width === p.value
                          ? "itzsa-editor-btn-primary"
                          : "itzsa-editor-btn",
                      )}
                    >
                      {p.label}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {error && (
              <p
                className="rounded-lg bg-[var(--editor-danger-bg)] px-3 py-2 text-[12px] text-[var(--editor-danger)]"
                role="alert"
              >
                {error}
              </p>
            )}
          </div>

          {/* Footer */}
          <div className="flex shrink-0 items-center justify-end gap-2 border-t border-[var(--editor-border)] bg-[var(--editor-surface)] px-5 py-3.5">
            <button
              type="button"
              onClick={onClose}
              className="itzsa-editor-btn h-9 rounded-lg px-4 text-[13px] font-medium"
            >
              {locale.cancel}
            </button>
            <button
              type="submit"
              disabled={!canInsert || uploading}
              className="itzsa-editor-btn-primary h-9 rounded-lg px-4 text-[13px] font-medium"
            >
              {locale.insert}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import {
  type NepaliInputMode,
  preetiMappings,
  unicodeMappings,
} from "@itzsa/nepali-input";
import { Extension } from "@tiptap/core";
import { Plugin } from "@tiptap/pm/state";

function getMapped(key: string, mode: NepaliInputMode): string | null {
  if (key.length !== 1) return null;
  const code = key.charCodeAt(0);
  if (code < 32 || code > 126) return null;
  const map = mode === "preeti" ? preetiMappings : unicodeMappings;
  return map[code - 32] ?? null;
}

export const createNepaliInputExtension = (mode: NepaliInputMode = "unicode") =>
  Extension.create({
    name: "nepaliInput",

    addOptions() {
      return { mode };
    },

    addProseMirrorPlugins() {
      const inputMode = this.options.mode as NepaliInputMode;
      const editor = this.editor;

      return [
        new Plugin({
          props: {
            handleKeyDown(_view, event: KeyboardEvent): boolean {
              // Let all modifier combos through — keeps Ctrl+B, Ctrl+Z etc.
              if (event.ctrlKey || event.metaKey || event.altKey) return false;
              // Only intercept single printable characters
              if (event.key.length !== 1) return false;

              const nepali = getMapped(event.key, inputMode);
              if (nepali === null) return false;

              event.preventDefault();
              editor.commands.insertContent(nepali);
              return true;
            },
          },
        }),
      ];
    },
  });

import type { NepaliInputMode } from "@itzsa/nepali-input";
import type { Extensions } from "@tiptap/core";
import { EditorContent } from "@tiptap/react";
import { CircleAlert } from "lucide-react";
import {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useMemo,
  useRef,
  useState,
} from "react";
import { EditorToolbar } from "./EditorToolbar";
import { cn } from "./lib/utils";
import { mergeLocale } from "./locale";
import { MediaModal } from "./MediaModal";
import { StatusBar } from "./StatusBar";
import { sanitizeHtml, validateMediaInsert } from "./security";
import { type EditorSettings, resolveEditorSettings } from "./settings";
import { TableModal } from "./TableModal";
import {
  DEFAULT_TOOLBAR_FEATURES,
  type EditorClassNames,
  type EditorToolbarFeatures,
  type MediaModalType,
  type RichTextEditorHandle,
} from "./types";
import type { EditorUploadHandler } from "./upload";
import { useEditorConfig } from "./useEditorConfig";

export type { RichTextEditorHandle } from "./types";

export interface RichTextEditorProps {
  value?: string;
  onChange?: (html: string) => void;
  onBlur?: () => void;
  onFocus?: () => void;
  placeholder?: string;
  label?: string;
  disabled?: boolean;
  readOnly?: boolean;
  invalid?: boolean;
  minHeight?: string;
  compact?: boolean;
  className?: string;
  classNames?: EditorClassNames;
  nepali?: NepaliInputMode | false;
  maxLength?: number;
  showStatusBar?: boolean;
  allowHtmlMode?: boolean;
  /**
   * Host upload handler — required for device file uploads.
   * Prefer `settings.media.onUpload` for production apps.
   */
  onUpload?: EditorUploadHandler;
  /**
   * @deprecated Use `settings.media.maxImageBytes` / `maxVideoBytes`.
   */
  maxUploadBytes?: number;
  toolbar?: EditorToolbarFeatures;
  locale?: EditorSettings["locale"];
  extensions?: Extensions;
  sanitize?: boolean;
  immediatelyRender?: boolean;
  /**
   * Scalable settings bag (media upload, limits, toolbar, locale, …).
   * Flat props still work and merge on top of / alongside this.
   */
  settings?: EditorSettings;
}

const FLASH_DURATION_MS = 2500;

export const RichTextEditor = forwardRef<
  RichTextEditorHandle,
  RichTextEditorProps
>(function RichTextEditor(
  {
    value = "",
    onChange,
    onBlur,
    onFocus,
    placeholder,
    label,
    disabled = false,
    readOnly = false,
    invalid = false,
    minHeight,
    compact,
    className,
    classNames,
    nepali,
    maxLength,
    showStatusBar,
    allowHtmlMode,
    onUpload,
    maxUploadBytes,
    toolbar: toolbarFeatures,
    locale: localeOverrides,
    extensions,
    sanitize,
    immediatelyRender,
    settings,
  },
  ref,
) {
  const resolved = useMemo(
    () =>
      resolveEditorSettings(settings, {
        placeholder,
        nepali,
        maxLength,
        minHeight,
        compact,
        showStatusBar,
        allowHtmlMode,
        sanitize,
        immediatelyRender,
        toolbar: toolbarFeatures,
        classNames,
        locale: localeOverrides,
        extensions,
        onUpload,
        maxUploadBytes,
      }),
    [
      settings,
      placeholder,
      nepali,
      maxLength,
      minHeight,
      compact,
      showStatusBar,
      allowHtmlMode,
      sanitize,
      immediatelyRender,
      toolbarFeatures,
      classNames,
      localeOverrides,
      extensions,
      onUpload,
      maxUploadBytes,
    ],
  );

  const locale = useMemo(
    () =>
      mergeLocale({
        ...resolved.locale,
        ...(resolved.placeholder ? { placeholder: resolved.placeholder } : {}),
      }),
    [resolved.locale, resolved.placeholder],
  );

  const features = useMemo(
    () => ({
      ...DEFAULT_TOOLBAR_FEATURES,
      ...resolved.toolbar,
      html: resolved.allowHtmlMode && (resolved.toolbar?.html ?? true),
    }),
    [resolved.toolbar, resolved.allowHtmlMode],
  );

  const [mediaModal, setMediaModal] = useState<MediaModalType>(null);
  const [tableModalOpen, setTableModalOpen] = useState(false);
  const [htmlMode, setHtmlMode] = useState(false);
  const [mediaError, setMediaError] = useState<string | null>(null);
  const [mounted, setMounted] = useState(false);
  const htmlRef = useRef<HTMLTextAreaElement>(null);
  const [flashVisible, setFlashVisible] = useState(false);
  const flashTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    setMounted(true);
  }, []);

  const handleLanguageBlock = useCallback(() => {
    setFlashVisible(true);
    if (flashTimer.current) clearTimeout(flashTimer.current);
    flashTimer.current = setTimeout(
      () => setFlashVisible(false),
      FLASH_DURATION_MS,
    );
  }, []);

  useEffect(
    () => () => {
      if (flashTimer.current) clearTimeout(flashTimer.current);
    },
    [],
  );

  const resolvedMinHeight =
    resolved.minHeight ?? (resolved.compact ? "160px" : "480px");
  const editable = !disabled && !readOnly;

  const editor = useEditorConfig({
    content: value,
    placeholder: locale.placeholder,
    editable,
    minHeight: resolvedMinHeight,
    nepali: resolved.nepali,
    onLanguageBlock: handleLanguageBlock,
    maxLength: resolved.maxLength,
    allowBase64: false,
    extensions: resolved.extensions,
    sanitize: resolved.sanitize,
    immediatelyRender: resolved.immediatelyRender,
  });

  const applyContent = useCallback(
    (html: string, emitUpdate: boolean): string => {
      if (!editor) return "";
      const next = resolved.sanitize
        ? sanitizeHtml(html, {
            allowDataImage: false,
            preserveEmpty: true,
          })
        : html;
      const normalized = next || "";
      editor.commands.setContent(normalized, { emitUpdate });
      return editor.isEmpty ? "" : editor.getHTML();
    },
    [editor, resolved.sanitize],
  );

  const lastPushed = useRef<string>(value);
  useEffect(() => {
    if (!editor) return;
    if (value !== lastPushed.current && value !== editor.getHTML()) {
      lastPushed.current = applyContent(value, false);
    }
  }, [editor, value, applyContent]);

  useEffect(() => {
    if (!editor) return;
    const handler = () => {
      const html = editor.isEmpty ? "" : editor.getHTML();
      lastPushed.current = html;
      onChange?.(html);
    };
    editor.on("update", handler);
    return () => {
      editor.off("update", handler);
    };
  }, [editor, onChange]);

  useEffect(() => {
    if (!editor) return;
    editor.setEditable(editable);
  }, [editor, editable]);

  useEffect(() => {
    if (!editor || !onBlur) return;
    editor.on("blur", onBlur);
    return () => {
      editor.off("blur", onBlur);
    };
  }, [editor, onBlur]);

  useEffect(() => {
    if (!editor || !onFocus) return;
    editor.on("focus", onFocus);
    return () => {
      editor.off("focus", onFocus);
    };
  }, [editor, onFocus]);

  useImperativeHandle(
    ref,
    () => ({
      getHTML: () => (editor?.isEmpty ? "" : (editor?.getHTML() ?? "")),
      getJSON: () => (editor?.getJSON() as Record<string, unknown>) ?? {},
      getText: () => editor?.getText() ?? "",
      setContent: (html, options) => {
        lastPushed.current = applyContent(html, options?.emitUpdate ?? true);
      },
      clear: () => {
        editor?.commands.clearContent(true);
        lastPushed.current = "";
      },
      focus: () => editor?.commands.focus(),
      blur: () => editor?.commands.blur(),
      isEmpty: () => editor?.isEmpty ?? true,
      getEditor: () => editor,
    }),
    [editor, applyContent],
  );

  const toggleHtmlMode = useCallback(() => {
    if (!editor || !resolved.allowHtmlMode) return;
    if (!htmlMode) {
      setHtmlMode(true);
    } else {
      const html = htmlRef.current?.value ?? "";
      lastPushed.current = applyContent(html, true);
      setHtmlMode(false);
    }
  }, [editor, htmlMode, resolved.allowHtmlMode, applyContent]);

  const handleInsertMedia = useCallback(
    (src: string, width?: string) => {
      if (!editor || !mediaModal) return;
      const result = validateMediaInsert({
        src,
        width,
        kind: mediaModal,
        allowBase64: false,
      });
      if (!result.ok) {
        setMediaError(result.error);
        return;
      }
      setMediaError(null);
      if (mediaModal === "image") {
        const chain = editor.chain().focus().setImage({ src: result.src });
        if (result.width) {
          chain.updateAttributes("image", { width: result.width });
        }
        chain.run();
      } else {
        editor
          .chain()
          .focus()
          .setVideo({
            src: result.src,
            width: result.width ?? null,
          })
          .run();
      }
      setMediaModal(null);
    },
    [editor, mediaModal],
  );

  const handleInsertTable = useCallback(
    (rows: number, cols: number) => {
      if (!editor) return;
      const r = Math.max(1, Math.min(20, rows));
      const c = Math.max(1, Math.min(20, cols));
      editor
        .chain()
        .focus()
        .insertTable({ rows: r, cols: c, withHeaderRow: true })
        .run();
    },
    [editor],
  );

  const rootClassNames = resolved.classNames;

  if (!mounted || !editor) {
    return (
      <div
        className={cn(
          "itzsa-editor flex min-h-[120px] items-center justify-center border border-[var(--editor-border)] text-sm text-[var(--editor-muted)]",
          className,
          rootClassNames?.root,
        )}
        style={{ minHeight: resolvedMinHeight }}
        aria-busy="true"
        aria-label={label}
      >
        Loading editor…
      </div>
    );
  }

  const currentHtml = editor.isEmpty ? "" : editor.getHTML();
  const limitHit =
    typeof resolved.maxLength === "number" &&
    (editor.storage.characterCount?.characters?.() ?? 0) >= resolved.maxLength;

  return (
    <>
      <div
        className={cn(
          "itzsa-editor flex flex-col overflow-hidden border shadow-sm",
          invalid &&
            "ring-2 ring-[var(--editor-danger)] border-[var(--editor-danger)]",
          disabled && "opacity-60 pointer-events-none",
          readOnly && "itzsa-editor-readonly",
          className,
          rootClassNames?.root,
        )}
        aria-label={label}
        aria-invalid={invalid || undefined}
        data-disabled={disabled || undefined}
        data-readonly={readOnly || undefined}
      >
        {!readOnly && (
          <EditorToolbar
            editor={editor}
            onOpenMedia={setMediaModal}
            onOpenTable={() => setTableModalOpen(true)}
            htmlMode={htmlMode}
            onToggleHtml={toggleHtmlMode}
            features={features}
            locale={locale}
            className={rootClassNames?.toolbar}
          />
        )}

        {flashVisible && (
          <div
            role="alert"
            aria-live="assertive"
            className="itzsa-editor-flash flex items-center gap-2 border-b px-4 py-2 text-xs font-medium"
          >
            <CircleAlert className="size-4 shrink-0" />
            {resolved.nepali ? locale.languageBlockNe : locale.languageBlockEn}
          </div>
        )}

        {limitHit && (
          <div
            role="status"
            className="itzsa-editor-flash flex items-center gap-2 border-b px-4 py-1.5 text-xs font-medium"
          >
            {locale.limitReached}
          </div>
        )}

        {htmlMode ? (
          <div
            className={cn("flex flex-1 flex-col", rootClassNames?.htmlPanel)}
          >
            <div className="itzsa-editor-html-bar flex items-center justify-between border-b px-4 py-2 font-mono text-xs">
              <span>{locale.htmlBanner}</span>
              <button
                type="button"
                onClick={toggleHtmlMode}
                className="itzsa-editor-btn rounded-md px-3 py-1 text-xs transition-colors"
              >
                {locale.htmlApply}
              </button>
            </div>
            <textarea
              ref={htmlRef}
              defaultValue={currentHtml}
              className="itzsa-editor-html-input w-full flex-1 resize-none px-4 py-4 font-mono text-sm leading-relaxed outline-none"
              style={{ minHeight: resolvedMinHeight }}
              spellCheck={false}
              aria-label={locale.htmlMode}
            />
          </div>
        ) : (
          <div
            className={cn(
              resolved.compact
                ? "px-3 py-3 sm:px-4"
                : "px-4 py-6 sm:px-8 sm:py-8 md:px-12 md:py-9",
              rootClassNames?.content,
            )}
          >
            <EditorContent editor={editor} />
          </div>
        )}

        {resolved.showStatusBar && !htmlMode && (
          <StatusBar
            editor={editor}
            nepali={resolved.nepali}
            maxLength={resolved.maxLength}
            locale={locale}
            className={rootClassNames?.statusBar}
          />
        )}
      </div>

      {mediaModal && (
        <MediaModal
          type={mediaModal}
          onClose={() => {
            setMediaModal(null);
            setMediaError(null);
          }}
          onInsert={handleInsertMedia}
          media={resolved.media}
          locale={locale}
          error={mediaError}
        />
      )}
      {tableModalOpen && (
        <TableModal
          onClose={() => setTableModalOpen(false)}
          onInsert={handleInsertTable}
          locale={locale}
        />
      )}
    </>
  );
});

